CHAPTER_4_EPIC = {
    'title': 'فصل چهارم: سیاه‌چال شمشیرزنان و لمس تب‌دار',
    'subtitle': 'علی پورسردار و مهدی بابایی؛ پیوند آتشین دو جنگجو در دخمه‌های نمور و کیمیای بی‌حسی لیدوکائین',
    'paragraphs': ['در اعماق نمور و تاریک سیاه\u200cچال\u200cهای ارگ ویرانشهر، جایی که نور خورشید هرگز بدان راه نیافته بود، بوی تعفن کاه پوسیده، مدفوع موش\u200cها، رطوبت کپک\u200cزده و خون خشکیده سنگفرش را پوشانده بود. علی پورسردار، شوالیه نیرومند با سینه\u200cای ستبر و بازوانی زخمی، در کنار مهدی بابایی، شمشیرزن چالاک با چشمانی نافذ و سیمایی استخوانی، با زنجیرهای پولادین به دیوار نمور بسته شده بودند. آنها سال\u200cها در جبهه\u200cهای مخالف، تیغ بر روی یکدیگر کشیده بودند؛ اما خیانت دکتر رضایی و بهزاد فروتن هر دو را به این سیاهچال کشانده بود.', 'زخم\u200cهای عمیق شمشیر بر شانه و سینه مهدی دهان گشوده بود و چرک و خوناب از آن فرو می\u200cچکید. مهدی از درد و تب شدید به خود می\u200cپیچید و ناله\u200cهایش سکوت خفقان\u200cآور سلول را می\u200cشکست. علی پورسردار با تلاش فراوان خود را به او نزدیک کرد؛ تن تب\u200cدار مهدی با پوستی زبر و داغ به سینه فراخ علی چسبید. حس کهنه\u200cای از کینه، در برابر گرمای تن رزمنده\u200cای که شانه به شانه\u200cاش جنگیده بود، فرو ریخت و جای خود را به عاطفه\u200cای مهارناپذیر و تنانه داد.', 'علی با دندان زنجیر بازوی چپش را شل کرد. در میان شکاف\u200cهای پوتین نظامی\u200cاش، ویالی کوچک از زایلوکائین (لیدوکائین ۲٪) پنهان شده بود. او شیشه را بیرون آورد و با صدایی بم و پرطنین گفت: «مهدی، آرام باش برادر... این کیمیای آمیدی است، بی\u200cحس\u200cکننده موضعی و داروی کلاس IB ضد آریتمی!» علی مایع شفاف لیدوکائین را بر لبه\u200cهای گوشت شکافته شانه مهدی ریخت. لیدوکائین با ورود به پایانه\u200cهای عصبی، کانال\u200cهای سدیم وابسته به ولتاژ (Voltage-gated Na+ channels) را در وضعیت غیرفعال بلوک کرد و مانع دپلاریزاسیون و انتقال پیام\u200cهای حاد درد به نخاع شد. در عرض دو دقیقه، فریادهای مهدی به نفس\u200cهایی آرام و بریده\u200cبریده بدل گشت.', 'اما شکنجه\u200cگران ارگ، زهر کینیدین را در آب خوری آنها ریخته بودند. ناگهان قلب مهدی دچار بی\u200cنظمی وحشتناکی شد؛ کینیدین با بلوک کانال\u200cهای پتاسیم تاخیری (IKr)، فاصله QT نوار قلب را به شدت طولانی کرده بود و موجبات آریتمی مرگبار تورساد دی پوینت (Torsades de pointes) را فراهم ساخته بود. مهدی به تشنج افتاد، نبضش مانند بال زدن گنجشک نامنظم شد و چشمانش رو به بالا برگشت.', 'علی پورسردار دستپاچه شد؛ او می\u200cدانست که در آریتمی ناشی از کینیدین یا مسمومیت با کارهای دهلیزی، لیدوکائین با کینتیک سریع اتصال و تفکیک (Rapid on-off) اختصاصاً به بافت بطنی دپلاریزه\u200cشده متصل می\u200cشود، اما پادزهر نهایی طولانی شدن QT، یون جادویی منیزیم است. علی از ته مانده سرم لیدوکائین چند قطره زیر زبان مهدی فشرد تا اکستراسیستول\u200cهای بطنی را مهار کند و سپس با دو دست، سینه عریان و ستبر مهدی را تحت ماساژ احیا قرار داد.', 'در آن ظلمت تنهایی و بوی مرگ، پیوندی عمیق و پرشور میان دو مرد شکوفا شد. مهدی با بازگشت هوشیاری، چشمانش را در چشمان علی دوخت. در چشمان علی جز تمنا و عطوفت نبود. مهدی لب\u200cهای تب\u200cدار و ترک\u200cخورده\u200cاش را بر لب\u200cهای پرقدرت علی گذاشت؛ بوسه\u200cای آتشین، بی\u200cپاک و سرشار از عطش سالیان نبرد. دو رزمنده تنومند، بر بستر خاک\u200cآلود سیاه\u200cچال در هم پیچیدند؛ گرمای پوست، زبری عضلات و بوی خون و مردانگی، وحشت شکنجه\u200cگاه را به جشن پیوند عاشقانه\u200cای دگرگون ساخت. آنها قسم یاد کردند که اگر زنده از این دخمه بیرون آیند، رگ\u200cهای ویرانشهر را از لوث وجود داروسازان تاریک پاک سازند.']
}

CHAPTER_5_EPIC = {
    'title': 'فصل پنجم: طغیان ادرار و لشکر بی‌پناه',
    'subtitle': 'فرماندهی یک‌روزه یاسر سربازی، آشوب دیورتیک‌ها، جنون باربیتورات‌ها و احیای فلومازنیل',
    'paragraphs': ['در پادگان مرکزی ویرانشهر، بوی گندیدگی و تعفن ادرار با غبار برخاسته از رژه سربازان در هم آمیخته بود. فرمانده کل پادگان برای ماموریتی به حومه رفته بود و در کمال بی\u200cتدبیری، فرماندهی بیست و چهار ساعته پادگان به یاسر سربازی واگذار شده بود؛ دلاوری نادان، حریص و شکم\u200cباره که از علم داروشناسی جز نام چند شربت نشاط\u200cآور نمی\u200cدانست. یاسر برای آنکه خود را پیش لشکریان محبوب سازد، تصمیم گرفت جیره\u200cهای آب پادگان را با «اکسیرهای لاغری، دفع بلغم و سبکی تن» تقویت کند!', 'او به انبارهای دارویی حمله برد و گونی\u200cهای سفید دیورتیک\u200cهای لوپ (فوروسماید / Lasix)، تیازیدها (هیدروکلروتیازید) و مهارکننده\u200cهای آلدوسترون (اسپیرونولاکتون / Aldactone) را در مخازن آب آشامیدنی ریخت و سربازان را وادار کرد پیش از مانور، سطل\u200cسطل از این آب تلخ بنوشند. یاسر با غرور فریاد می\u200cزد: «بنوشید تا تمام خستگی\u200cها و آب\u200cهای زاید تن\u200cتان بیرون بریزد و چون عقاب بر دشمن بتازید!»', 'تنها دو ساعت بعد، فاجعه فارماکولوژیک پادگان را به جهنم بدل کرد! فوروسماید با مهار هم\u200cترانسپورت Na+/K+/2Cl- در شاخه ضخیم بالارونده قوس هنله (TAL)، سد بازجذب آب و نمک را منهدم کرده بود؛ همزمان هیدروکلروتیازید با مهار انتقال سدیم-کلر در لوله دیستال، اثر هم\u200cافزایی فوق\u200cالعاده سهمگینی پدید آورده بود. سیلابی از ادرار از تن هزاران سرباز جاری شد. سربازان سلاح\u200cها را افکنده و با شلوارهای خیس در محوطه پادگان صف کشیده بودند؛ مستراح\u200cها سرریز شدند و محوطه به لجن\u200cزاری از ادرار و کف بدل گشت.', 'افت شدید حجم خون (هیپوولمی)، افت فشار خون وضعیتی و از همه مهلک\u200cتر، دفع انبوه پتاسیم (هیپوکالمی شدید به زیر ۲/۵ mEq/L) لشکر را زمین\u200cگیر کرد. سربازان دچار فلج شل عضلانی، کرامپ\u200cهای زجرآور پاها و آریتمی\u200cهای قلبی شدند. زبان\u200cهایشان چون چوب خشکیده بود و از تشنگی نعره می\u200cزدند.', 'یاسر سربازی که پادگان را در اثر دیورز سهمگین به ویرانه\u200cای بدبو بدل کرده بود، برای خاموش کردن شورش لشکریان، دست به حماقتی ویرانگرتر زد. او در میانه شب، خمره\u200cهای بزرگ شراب را با آرامبخش\u200cهای سنگین باربیتوراتی و بنزودیازپینی درآمیخت: پودر فنوباربیتال، تیوپنتال سدیم و مقادیر هنگفتی از دیازپام، لورازپام و میدازولام. یاسر جار زد: «این کیمیای خواب بهشتی است! بنوشید و درد را فراموش کنید!»', 'سربازان تشنه، خمره\u200cها را سر کشیدند. اما ترکیب باربیتورات با الکل و بنزودیازپین، کابوسی مرکب از سرکوب افزایشی بر گیرنده\u200cهای GABAA پدید آورد. باربیتورات\u200cها مدت زمان باز ماندن کانال\u200cهای کلرید را چند برابر کردند و بنزودیازپین\u200cها فرکانس باز شدن را به اوج رساندند؛ نورون\u200cهای بصل\u200cالنخاع یکی پس از دیگری خاموش شدند. سکوتی مرگبار بر پادگان حاکم شد. ده\u200cها سرباز با تنفس\u200cهای کندتر از چهار بار در دقیقه و لب\u200cهای سیانوزه به کما رفتند.', 'در این هنگام، شبح علی\u200cرضا رئیسی چون نسیمی از تاریکی پدیدار گشت. او فریاد زد: «سریعاً راه هوایی را با لوله\u200cگذاری باز کنید! فلومازنیل جایگاه اتصالی بنزودیازپین\u200cها را بر گیرنده گابا مسدود می\u200cکند، اما برای باربیتورات\u200cها باید ادرار را با انفوزیون بی\u200cکربنات سدیم قلیایی کنید تا یونیزه شده و از لوله\u200cهای کلیوی بازجذب نشود!» با تزریق تیتراسیون\u200cشده فلومازنیل، انفوزیون بیکربنات و سرم\u200cهای کلرید پتاسیم، تنفس دلاوران بازگشت و یاسر سربازی از وحشت مجازات در لجنزار محوطه پادگان پنهان شد.']
}

CHAPTER_6_EPIC = {
    'title': 'فصل ششم: قفل بر شریان‌های زندگی',
    'subtitle': 'بحران فشار خون در محاصره ارگ، متسع‌کننده‌های عروق، نیتروپروساید و مسدودکننده‌های کلسیم',
    'paragraphs': ['سپاهیان مزدور دکتر رضایی و بهزاد فروتن، دروازه\u200cهای محله جنوبی ویرانشهر را به توپ بستند. دیوارهای سنگی زیر باران گلوله\u200cهای آتشین می\u200cلرزیدند. استرس سهمگین نبرد، فوران کاتکول\u200cآمین\u200cهای سمپاتیک و انقباض عروقی شدید، پرفشاری خون حاد و اورژانس (Hypertensive Crisis) را در میان مدافعان پدید آورده بود؛ فشار خون بسیاری از دلاوران از ۲۲۰/۱۴۰ میلی\u200cمتر جیوه گذشته بود و خطر خونریزی مغزی، پارگی دیسکسیون آئورت و ادم حاد ریه هر لحظه جان\u200cها را تهدید می\u200cکرد.', 'حسام دانش در برج دیده\u200cبانی، فرماندهی خط پدافند همودینامیک را به دست گرفت. او می\u200cدانست که در بحران فشار خون، کاهش ناگهانی و سقوط آزاد پرفیوژن می\u200cتواند ایسکمی مغزی ایجاد کند. او داروی نیتروپروساید سدیم را از طریق انفوزیون با پمپ وریدی برقرار ساخت. بطری نیتروپروساید را با پارچه\u200cای ضخیم و مات پوشاندند تا از تجزیه نوری آن به یون\u200cهای سمی سیانید جلوگیری شود.', 'نیتروپروساید با آزادسازی مستقیم اکسید نیتریک، همزمان شریانچه\u200cها و وریدچه\u200cها را گشاد کرد و بار پس و بار پیش را کاهش داد. برای کنترل مسمومیت احتمالی با سیانید، حسام تیوسولفات سدیم را در خط وریدی آماده نگاه داشت. همزمان در رزمندگانی که دچار فئوکروموسیتوما و تاکی\u200cکاردی رفلکسی بودند، مسدودکننده توأم آلفا و بتا یعنی لابتالول وریدی و فنولدوپام (آگونیست D1 با حفظ خونرسانی کلیه) را به کار گرفتند.', 'در سنگرهای مجاور، داروهای خوراکی مسدودکننده کانال کلسیم دی\u200cهیدروپیریدینی چون نیفدیپین و آملودیپین، و مهارکننده\u200cهای سیستم رنین-آنژیوتانسین چون کاپتوپریل و لوزارتان میان مجروحان توزیع شد. کاپتوپریل با مهار تبدیل آنژیوتانسین I به آنژیوتانسین II، بار مقاومت محیطی را شکست؛ هرچند سرفه\u200cهای خشک و آزاردهنده ناشی از تجمع برادی\u200cکینین گلوی سربازان را می\u200cخراشید و به لوزارتان (ARB) سوئیچ شدند. با مهار فشار خون و تثبیت همودینامیک، خط دفاعی ارگ استوار ماند و موج اول حمله مزدوران در هم شکست.']
}

CHAPTER_7_EPIC = {
    'title': 'فصل هفتم: جنگ خون و لخته در سایه‌ها',
    'subtitle': 'معید براهویی در کارگاه زیرزمینی؛ ضد انعقادها، آبشار فیبرین و پادزهرهای هموستاتیک',
    'paragraphs': ['در مجاری زیرزمینی و شبکه فاضلاب\u200cهای متروکه ویرانشهر، معید براهویی، زاهد گوشه\u200cگیر و بدبین زیرزمین، کارگاه تقطیر خونین خود را برپا کرده بود. معید از اجتماع گریزان بود و با خفاش\u200cها و موش\u200cها هم\u200cکلام می\u200cشد، اما وفاداری\u200cاش به حسام دانش و یاران مقاومت تزلزل\u200cناپذیر بود. در برابر او، لوله\u200cهای آزمایشگاهی حاوی پلاسمای غلیظ، فاکتورهای انعقادی و زهر مارهای جعفری قرار داشت.', 'معید با صدایی خشن و توخالی زمزمه کرد: «ترومبوز، هیولایی است که در سکون رگ\u200cها زاده می\u200cشود. آبشار انعقاد چون دومینو فرو می\u200cریزد: فاکتور بافتی فعال می\u200cشود، فاکتور ده فعال (Xa) پروترومبین را به ترومبین (فاکتور IIa) می\u200cشکافد و ترومبین شبکه فیبرین را می\u200cتند تا گلبول\u200cهای قرمز و پلاکت\u200cهای فعال\u200cشده توسط ترومبوکسان A2 در این دام خفه شوند!»', 'او شیشه\u200cهای هپارین تجزیه\u200cنشده (UFH) و انوکساپارین (Lovenox) را به حسام تحویل داد: «هپارین مانند صاعقه\u200cای بر آنتی\u200cترومبین III فرود می\u200cآید و قدرت مهاری آن را هزار برابر می\u200cسازد تا ترومبین و فاکتور ده را در جا نابود کند. اما اگر پلاکت\u200cها افت کردند و ترومبوسیتوپنی ایمونولوژیک (HIT) رخ داد، فوراً هپارین را قطع کنید و به مهارکننده\u200cهای مستقیم ترومبین چون آرگاتروبان یا دابیگاتران پناه برید! و اگر خونریزی مهارناپذیر شد، پادزهر پروتامین سولفات با بار مثبت کاتیونی\u200cاش هپارین منفی را خنثی خواهد کرد.»', 'معید همچنین کپسول\u200cهای پودری وارفارین را نشان داد: «این زهر کومارینی است؛ آنزیم ویتامین K اپوکسید ردوکتاز کبد را کور می\u200cکند و فاکتورهای وابسته به ویتامین K — دو، هفت، نه و ده — را ناقص می\u200cسازد. مراقب باشید که این سم را هرگز به زنان باردار ندهید، چرا که اسکلت و بینی جنین را منهدم می\u200cسازد! و پادزهر آن ویتامین K1 (فیتونادیون) و ترانگزامیک اسید (TXA) است که مهارکننده فیبرینولیز است.» با این سلاح\u200cهای بیوشیمیایی، جنگ مخفی علیه آمبولی\u200cها و لخته\u200cهای ترومبوتیک در رگ\u200cهای مقاومت آغاز شد.']
}
